// ── Validate & Generate Ticket ID ──
const body = $input.item.json.body || $input.item.json;
const errors = [];
const log = [];

log.push(`[${new Date().toISOString()}] Ticket received`);

// Required fields
const name = (body.Name || body.name || '').toString().trim();
const email = (body.Email || body.email || '').toString().trim();
const subject = (body.Subject || body.subject || '').toString().trim();
const message = (body.Message || body.message || '').toString().trim();

if (!name)    errors.push('Name is required');
if (!email)   errors.push('Email is required');
if (!subject) errors.push('Subject is required');
if (!message || message.length === 0) errors.push('Message body is required and must not be empty');

// Email format validation
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
if (email && !emailRegex.test(email)) {
  errors.push('Email must be a valid format (e.g. user@example.com)');
}

const newItem = {};
if ($input.item.binary) {
  newItem.binary = $input.item.binary;
}

if (errors.length > 0) {
  log.push(`[${new Date().toISOString()}] Validation FAILED: ${errors.join('; ')}`);
  newItem.json = {
    valid: false,
    errors,
    processing_log: log.join('\n')
  };
  return newItem;
}

// Generate ticket ID  (TKT-YYYYMMDD-XXXX)
const now = new Date();
const datePart = now.toISOString().slice(0,10).replace(/-/g,'');
const rand = Math.random().toString(36).substr(2, 6).toUpperCase();
const ticketId = `TKT-${datePart}-${rand}`;

log.push(`[${new Date().toISOString()}] Validation passed — Ticket ID: ${ticketId}`);

newItem.json = {
  valid: true,
  ticket_id: ticketId,
  timestamp: now.toISOString(),
  Name: name,
  Email: email,
  Subject: subject,
  Message: message,
  processing_log: log.join('\n')
};

return newItem;

// ── Merge PDF text (if successful) into Message ──
const prev = $('Validate Input & Generate ID').item.json;
let log = prev.processing_log || '';
let message = prev.Message;

// Check if PDF extraction succeeded (handles .text or .data)
const extractedText = $input.item.json?.text || $input.item.json?.data || '';
const extractionError = $input.item.json?.error;

if (extractionError || extractedText.length === 0) {
  log += `\n[${new Date().toISOString()}] PDF extraction returned no text — processing as text-only ticket`;
} else {
  log += `\n[${new Date().toISOString()}] PDF text extracted successfully (${extractedText.length} chars)`;
  message = message + '\n\n--- Attached PDF Content ---\n' + extractedText;
}

return {
  json: {
    ticket_id: prev.ticket_id,
    timestamp: prev.timestamp,
    Name: prev.Name,
    Email: prev.Email,
    Subject: prev.Subject,
    Message: message,
    processing_log: log
  }
};

// ── Pass through without PDF ──
const prev = $('Validate Input & Generate ID').item.json;
let log = prev.processing_log || '';
log += `\n[${new Date().toISOString()}] No attachment — proceeding with text-only ticket`;

return {
  json: {
    ticket_id: prev.ticket_id,
    timestamp: prev.timestamp,
    Name: prev.Name,
    Email: prev.Email,
    Subject: prev.Subject,
    Message: prev.Message,
    processing_log: log
  }
};

// ── Merge classification result with ticket data ──
let ticket;
try { ticket = $('No Attachment (Pass Through)').item.json; } catch(e) {}
if (!ticket) try { ticket = $('Merge PDF into Ticket').item.json; } catch(e) {}
const classification = $input.item.json?.output || $input.item.json || {};
let log = ticket.processing_log || '';

if ($input.item.json?.error || !classification.Category) {
  log += `\n[${new Date().toISOString()}] Classification LLM failed: ${$input.item.json?.error?.message || 'Unknown error'}`;
  return {
    json: {
      ...ticket,
      Category: "general",
      Urgency: "medium",
      Sentiment: "neutral",
      Confidence: 0.0,
      Summary: "Classification failed due to AI error.",
      processing_log: log,
      error: true
    }
  };
}

log += `\n[${new Date().toISOString()}] Classification complete — Category: ${classification.Category}, Urgency: ${classification.Urgency}, Confidence: ${classification.Confidence}`;

return {
  json: {
    ticket_id: ticket.ticket_id,
    timestamp: ticket.timestamp,
    Name: ticket.Name,
    Email: ticket.Email,
    Subject: ticket.Subject,
    Message: ticket.Message,
    Category: classification.Category || "general",
    Urgency: classification.Urgency || "medium",
    Sentiment: classification.Sentiment || "neutral",
    Confidence: classification.Confidence || 0,
    Summary: classification.Summary || "Failed to parse summary",
    processing_log: log
  }
};

