// -- Build final ticket record before routing --
const merged = $('Merge Classification Results').item.json;
let log = merged.processing_log || '';

let ragOutput = "";
if ($input.item.json?.error || merged.error) {
  log += `\n[${new Date().toISOString()}] RAG generation failed: ${$input.item.json?.error?.message || 'Unknown error or upstream error'}`;
  ragOutput = "We apologize, but we are currently experiencing high volume and our automated drafting failed. A human agent will review this ticket soon.";
} else {
  ragOutput = $input.item.json.output || $input.item.json.text || '';
  log += `\n[${new Date().toISOString()}] RAG draft response generated (${ragOutput.length} chars)`;
}

// Strict retrieval-quality gate: require a numeric top similarity score
const RETRIEVAL_THRESHOLD = 0.45;
const scoreCandidates = [
  $input.item.json?.retrieval_top_score,
  $input.item.json?.retrievalTopScore,
  $input.item.json?.top_similarity_score,
  $input.item.json?.topSimilarityScore,
  $input.item.json?.similarity_score,
  $input.item.json?.similarityScore,
  $input.item.json?.retrieval?.top_score,
  $input.item.json?.retrieval?.topScore,
  $input.item.json?.retrieval?.score,
  $input.item.json?.metadata?.retrieval?.top_score,
  $input.item.json?.metadata?.retrieval?.topScore,
  $input.item.json?.metadata?.retrieval?.score,
  Array.isArray($input.item.json?.retrieval?.scores) ? $input.item.json.retrieval.scores[0] : undefined,
  Array.isArray($input.item.json?.scores) ? $input.item.json.scores[0] : undefined,
];

let retrievalTopScore = null;
for (const candidate of scoreCandidates) {
  const value = Number(candidate);
  if (Number.isFinite(value)) {
    retrievalTopScore = value;
    break;
  }
}

const retrievalScoreAvailable = Number.isFinite(retrievalTopScore);
const retrievalLowConfidence = !retrievalScoreAvailable || retrievalTopScore < RETRIEVAL_THRESHOLD;
if (retrievalLowConfidence) {
  const reason = retrievalScoreAvailable
    ? `top similarity ${retrievalTopScore.toFixed(3)} < ${RETRIEVAL_THRESHOLD}`
    : 'top similarity score missing or non-numeric';
  log += `\n[${new Date().toISOString()}] LOW RETRIEVAL CONFIDENCE (${reason})`;

  if (!ragOutput.includes('No specific policy found')) {
    ragOutput = `${ragOutput}\n\nNote: No specific policy found - this response is based on general knowledge.`.trim();
  }
}

// Determine status based on pipeline failures + classification confidence + retrieval quality
const confidence = parseFloat(merged.Confidence) || 0;
let status = (merged.error || $input.item.json?.error) ? 'failed' : 'processed';
if (status !== 'failed' && (confidence < 0.6 || retrievalLowConfidence)) {
  status = 'needs-manual-review';
}
if (status === 'needs-manual-review' && confidence < 0.6) {
  log += `\n[${new Date().toISOString()}] LOW CLASSIFICATION CONFIDENCE (${confidence}) - flagged for manual review`;
}

// Extract knowledge sources from the RAG response text (look for [Source: x])
let knowledgeSources = 'N/A';
const sourceMatches = ragOutput.match(/\[Source:\s*([^\]]+)\]/gi);
if (sourceMatches) {
  knowledgeSources = [...new Set(sourceMatches.map(s => s.replace(/\[Source:\s*|\]/gi, '').trim()))].join(', ');
} else if (ragOutput.includes('No specific policy found') || ragOutput.includes('general knowledge')) {
  knowledgeSources = 'None - general knowledge response';
} else {
  const fallbackMatches = ragOutput.match(/(?:refund|shipping|account|password|privacy|gdpr|sla|api|rate|acceptable|subscription|troubleshooting|faq|policy|documentation)/gi);
  if (fallbackMatches) {
     knowledgeSources = [...new Set(fallbackMatches.map(s => s.toLowerCase()))].join(', ');
  }
}

log += `\n[${new Date().toISOString()}] Final status: ${status}`;

return {
  json: {
    ticket_id: merged.ticket_id,
    timestamp: merged.timestamp,
    Name: merged.Name,
    Email: merged.Email,
    Subject: merged.Subject,
    Message: merged.Message,
    Category: merged.Category,
    Urgency: merged.Urgency,
    Sentiment: merged.Sentiment,
    Confidence: confidence,
    Summary: merged.Summary,
    draft_response: ragOutput,
    knowledge_sources: knowledgeSources,
    retrieval_top_score: retrievalTopScore,
    retrieval_low_confidence: retrievalLowConfidence,
    status: status,
    processing_log: log
  }
};
